INSERT INTO drug_interactions (id,drug1_id,drug2_id,severity,mechanism,clinical_effect,management) VALUES
  (1,26,2,'severe','Competition at COX-1 binding site','Ibuprofen blunts the cardioprotective antiplatelet effect of aspirin.','Give aspirin at least 2 hours before ibuprofen, or use paracetamol.'),
  (2,21,3,'severe','Reduced renal prostaglandin synthesis','Concurrent NSAID and ACE inhibitor may precipitate acute kidney injury.','Avoid in renal impairment; monitor creatinine and potassium.'),
  (3,20,22,'mild','Additive antihypertensive effect','Enhanced blood pressure lowering, occasionally symptomatic hypotension.','Usually intended; monitor postural blood pressure.'),
  (4,23,21,'moderate','Volume depletion plus RAAS blockade','First-dose hypotension and rising creatinine.','Start low, review renal function within a week.'),
  (5,39,41,'moderate','CYP3A4 inhibition','Raised carbamazepine levels causing ataxia and drowsiness.','Monitor levels; consider an alternative antidepressant.'),
  (6,7,40,'mild','Uncertain','Reports of raised valproate levels.','Clinical monitoring is sufficient.'),
  (7,8,35,'moderate','Chelation in the gut','Iron markedly reduces ciprofloxacin absorption.','Separate doses by at least 2 hours.'),
  (8,31,35,'mild','Reduced gastric acidity','Impaired iron absorption.','Take iron with vitamin C, review response.'),
  (9,43,42,'severe','Serotonergic and anticholinergic additive effect','Risk of serotonin syndrome and QT prolongation.','Avoid combination; if unavoidable, ECG and close monitoring.'),
  (10,29,3,'moderate','Additive gastric mucosal injury','Increased risk of peptic ulceration and bleeding.','Add gastroprotection; use the shortest possible course.'),
  (11,25,8,'mild','CYP3A4 competition','Small increase in statin exposure and myalgia risk.','Advise reporting muscle pain.'),
  (12,38,43,'moderate','Additive CNS depression','Excessive sedation and respiratory depression.','Reduce doses; monitor sedation score.');
